function applyExpRate(rate){var s=state();s.expMultiplier=Math.max(0,num(rate,1));if(g.Game_Actor&&Game_Actor.prototype&&!Game_Actor.prototype.__rpgrtlExpPatched){var old=Game_Actor.prototype.gainExp;Game_Actor.prototype.__rpgrtlExpPatched=true;Game_Actor.prototype.gainExp=function(v){return old.call(this,Math.round(num(v,0)*num(state().expMultiplier,1)))}}}
